INSERT INTO public.profession_tracks (id,profession_name,icon,description,color_accent) VALUES
('avukat','Avukat','gavel','Hakkı savunurken doğruluğu, taraflar arasında adaleti ve mahremiyeti koru.','#6d28d9'),
('eczaci','Eczacı','pill','İlaç bilgisini güvenlik, mahremiyet ve danışmanlık sorumluluğuyla birleştir.','#0891b2'),
('muhasebeci','Muhasebeci','calculator','Mali kayıtlarda doğruluğu, çıkar çatışmasında bağımsızlığı ve müşteri sırrını koru.','#059669'),
('hemsire','Hemşire','heart-rate-monitor','Bakım verirken şefkat, mahremiyet ve hasta güvenliğini birlikte gözet.','#e11d48')
INSERT INTO public.profession_lessons (id,track_id,title,order_index,duration_estimate_minutes,content_body,source_references,xp_reward) VALUES
('avukat-1','avukat','Niyet: işi ibadet bilinciyle başlatmak',1,6,'{"openingType":"hadis","openingArabic":"إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ","openingText":"Ameller niyetlere göredir; herkese niyet ettiği vardır.","explanation":"Meslek yalnızca gelir üreten bir rol değildir. Helal rızık, insanlara fayda ve sorumluluğu hakkıyla taşıma niyeti; aynı işi daha bilinçli, ölçülebilir ve dürüst yapmaya yön verir. Niyet, teknik standardın yerine geçmez; onu neden koruduğunu hatırlatır.","action":"Bugünkü en önemli işinin başına tek cümlelik bir niyet yaz: “Bu işi ... faydası ve Allah’ın rızası için özenle tamamlayacağım.”"}'::jsonb,'[{"label":"Sahih el-Buhârî 1 · Ameller niyetlere göredir","url":"https://sunnah.com/bukhari:1"}]'::jsonb,30),
('avukat-2','avukat','Amanah: yetki, bilgi ve zaman birer emanettir',2,7,'{"openingType":"ayet","openingArabic":"إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الْأَمَانَاتِ إِلَى أَهْلِهَا","openingText":"Allah size, emanetleri mutlaka ehline vermenizi emrediyor.","explanation":"Bir projeye erişim, müşteri bilgisi, kurum bütçesi, ekip zamanı ve verilen yetki emanet kapsamındadır. Emanet bilinci; gizliliği korumayı, çıkar çatışmasını bildirmeyi ve yetkin olmadığın konuda destek istemeyi profesyonel karakterin parçası yapar.","action":"Bugün taşıdığın üç emaneti yaz: bilgi, zaman ve karar. Her biri için tek bir koruma davranışı belirle."}'::jsonb,'[{"label":"Nisâ 4:58 · Emanet ve ehliyet","url":"https://kuran.diyanet.gov.tr/mushaf/kuran-tefsir-1/nisa-suresi-4/ayet-58/diyanet-isleri-baskanligi-meali-1"}]'::jsonb,30),
('avukat-3','avukat','İhsan: kaliteyi görünür bir standarda dönüştürmek',3,8,'{"openingType":"hadis","openingArabic":"إِنَّ اللَّهَ كَتَبَ الإِحْسَانَ عَلَى كُلِّ شَيْءٍ","openingText":"Allah her şeyde ihsanı gerekli kılmıştır.","explanation":"Sahih Müslim’deki hadis ihsanı somut bir uygulama üzerinden öğretir: işi özensizliğe bırakmamak ve gereksiz acıyı önlemek. Meslekte ihsan; kontrol listesi, akran incelemesi, hata kaydı ve sürekli iyileştirme gibi doğrulanabilir kalite pratikleriyle görünür olur.","action":"Teslim edeceğin bir işi ikinci kez kontrol et; bulduğun bir iyileştirmeyi kayda geçir."}'::jsonb,'[{"label":"Sahih Müslim 1955a · Her işte ihsan","url":"https://sunnah.com/muslim:1955a"}]'::jsonb,30),
('avukat-4','avukat','Sıdk: hatayı ve sınırı saklamadan söylemek',4,7,'{"openingType":"hadis","openingArabic":"مَنْ غَشَّ فَلَيْسَ مِنِّي","openingText":"Bizi aldatan bizden değildir.","explanation":"Bir kusuru, gecikmeyi, veri sınırını veya çıkar çatışmasını saklamak kısa vadede rahatlık sağlayabilir; fakat güveni ve karar kalitesini bozar. Profesyonel doğruluk, yalnızca yalan söylememek değil, karşı tarafın kararını etkileyen önemli bilgiyi zamanında açıklamaktır.","action":"Bugün bir rapor veya konuşmada varsayım, risk ve kesin olmayan noktaları açıkça etiketle."}'::jsonb,'[{"label":"Sahih Müslim 102 · Aldatma yasağı","url":"https://sunnah.com/muslim:102"}]'::jsonb,30),
('avukat-5','avukat','Denge: işin, bedenin, ailenin ve ibadetin hakkı',5,6,'{"openingType":"hadis","openingArabic":"فَأَعْطِ كُلَّ ذِي حَقٍّ حَقَّهُ","openingText":"Her hak sahibine hakkını ver.","explanation":"Sürekli tükenme hâli uzun vadede ne kişiye ne hizmet verdiği insanlara fayda sağlar. Sınır koymak, dinlenmek, ibadet vakitlerini ve aile sorumluluğunu planlamak; sürdürülebilir performansın ahlâkî tarafıdır.","action":"Takviminde bugün iş, ibadet, dinlenme ve yakınların için gerçekçi birer zaman sınırı oluştur."}'::jsonb,'[{"label":"Sahih el-Buhârî 1968 · Her hak sahibine hakkı","url":"https://sunnah.com/bukhari:1968"}]'::jsonb,30),
('avukat-6','avukat','Müvekkil sırrı ve mahremiyet emaneti',6,8,'{"openingType":"ayet","openingText":"Allah size, emanetleri mutlaka ehline vermenizi emrediyor.","explanation":"Emanet ilkesi, müvekkilin paylaştığı bilginin yalnızca yetkili kişilerce ve işin gerektirdiği ölçüde kullanılmasını hatırlatır. Dosya erişimi, görüşme ortamı ve paylaşım kanalı gizlilik açısından birlikte değerlendirilir; somut yükümlülükler ilgili mevzuat ve meslek kurallarıyla doğrulanır.","action":"Bugün bir dosyanın erişim izinlerini, yetki sınırların içinde gereksiz paylaşım açısından kontrol et."}'::jsonb,'[{"label":"Nisâ 4:58 · Emanet ve ehliyet","url":"https://kuran.diyanet.gov.tr/mushaf/kuran-tefsir-1/nisa-suresi-4/ayet-58/diyanet-isleri-baskanligi-meali-1"}]'::jsonb,30),
('avukat-7','avukat','Adalet önünde tarafsızlık',7,9,'{"openingType":"ayet","openingText":"Adaletli olun; bu, takvâya daha uygundur.","explanation":"Hak savunmak, karşı tarafın insan onurunu veya delilin sınırlarını yok saymayı gerektirmez. Ayetin adalet çağrısını meslek pratiğine taşırken kişisel yakınlıkları, önyargıları ve çıkar çatışmalarını değerlendirmeden ayırmak gerekir.","action":"İncelediğin bir olayda olguları, varsayımları ve kişisel kanaatleri üç ayrı başlık altında işaretle."}'::jsonb,'[{"label":"Mâide 5:8 · Adalet takvâya daha yakındır","url":"https://kuran.diyanet.gov.tr/mushaf/kuran-tefsir-1/M%C3%A2ide-S%C3%BBresi-5/ayet-6/kuran-yolu-meali-5"}]'::jsonb,30),
('avukat-8','avukat','Delil ve beyanda doğruluk',8,8,'{"openingType":"ayet","openingText":"Bir haber geldiğinde doğruluğunu araştırın.","explanation":"Haberi doğrulama sorumluluğu, iddiayı kesinleşmiş olgu gibi sunmamak için bir ahlâkî hatırlatmadır. Bir belgenin kaynağı, tarihi ve bağlamı kontrol edilmeli; doğrulanamayan noktalar açıkça belirtilmelidir.","action":"Bugün kullandığın bir belgenin ilk kaynağını ve tarihini kontrol ederek belirsiz noktaları not et."}'::jsonb,'[{"label":"Hucurât 49:6 · Haberi araştırma sorumluluğu","url":"https://kuran.diyanet.gov.tr/mushaf/kuran-meal-2/hucurat-suresi-49/ayet-6/diyanet-isleri-baskanligi-meali-1"}]'::jsonb,30),
('eczaci-1','eczaci','Niyet: işi ibadet bilinciyle başlatmak',1,6,'{"openingType":"hadis","openingArabic":"إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ","openingText":"Ameller niyetlere göredir; herkese niyet ettiği vardır.","explanation":"Meslek yalnızca gelir üreten bir rol değildir. Helal rızık, insanlara fayda ve sorumluluğu hakkıyla taşıma niyeti; aynı işi daha bilinçli, ölçülebilir ve dürüst yapmaya yön verir. Niyet, teknik standardın yerine geçmez; onu neden koruduğunu hatırlatır.","action":"Bugünkü en önemli işinin başına tek cümlelik bir niyet yaz: “Bu işi ... faydası ve Allah’ın rızası için özenle tamamlayacağım.”"}'::jsonb,'[{"label":"Sahih el-Buhârî 1 · Ameller niyetlere göredir","url":"https://sunnah.com/bukhari:1"}]'::jsonb,30),
